      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n급급급) 7/28~30) 2시간~2시간반 15만) 20세이상 남녀 ) 직장 내 괴롭힘 관련 재직자(근로자) 줌 화상 인터뷰\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.07.27. 08:34\n조회 40\n구독\n급급급) 7/28~30) 2시간~2시간반 15만) 20세이상 남녀 ) 직장 내 괴롭힘 관련 재직자(근로자) 줌 화상 인터뷰\n신청하신분은 재신청 안하셔도 됩니다\n직장 내 괴롭힘 예방과 대응체계의 현황 및 한계를 진단하고, 보다 실효성 있는 직장 내 괴롭힘 금지제도의 개선방안을 마련하기 위한 연구를 진행하고 있습니다.\n정량적으로 파악하기 힘든 제도 운영 과정의 구체적 경험, 현장의 어려움, 제도 개선 필요성 등을 파악하기 위하여 인사담당자, 피해근로자, 법률 전문가 그룹별로 Focus Group Interview(좌담회)를 진행하고자 하오니, 연구가 원활하게 진행될 수 있도록 적극적인 협조를 부탁드립니다. 감사합니다.\n구분\n내용\n대상/조건\n○ 직장인(정규직/계약직/단기 근로자 등)\n(재직 증빙 가능한 경우에만 대상자로 선정 가능)\n○ 직장 내 괴롭힘을 경험하신분\n일정\n7월 28~30일중 하루 저녁 7시~ 9시( 2시간 ~ 2시간 30분 소요 예정)\n방법\n줌(ZOOM)을 활용한 화상 인터뷰(참석 인원 5인)\n줌 관련해서 반드시 얼굴이 나오게 진행하므로 착오 없으시기 바랍니다\n가능하신분만 신청해주세요\n사례\n세후 15만원 지급(지급 동의서 작성, 8.8% 기타소득세 공제 후 당일 계좌 지급)\n문의\n한국사회조사연구소\nq1. 회사의 업종\n(주 생산/서비스 내용)\nq2. 화사의 상시 근로자 수\n(-> 5인 이상 선택 시 종료\n‘협조해 주셔서 감사합니다’)\nq3. 직장 내 괴롭힘 직접 경험 유무\n① 경험 있음 ② 경험 없음(-> ②번 선택시 종료‘협조해 주셔서 감사합니다’)\nq4. 근무형태\n① 정규직 ② 계약직 ③ 임시직\nq5. 본인의 업무\nq6. 현 직장 근무\n시작 년도\n년\nq7. 가장 최근 직장 내 괴롭힘 경험년도\n년\n(현재, 이전회사 상관없음)\nq8.\n가장 최근 직접 경험한 직장 내 괴롭힘 유형 모두 선택\n① 폭언·모욕 등 언어적 괴롭힘\n② 따돌림, 무시 등 관계적 괴롭힘\n③ 과도한 업무, 업무 배제, 부당한 인사 평가 등 업무·인사상 괴롭힘\n④ 업무 외 지시, 사생활 간섭 등 부당한 지시\n⑤ 성별, 나이, 고용형태 등에 따른 차별적 괴롭힘\n⑥ 밀치기, 물건 던지기 등 신체적·위협적 괴롭힘\nq9.\n가장 최근 직접 경험시 대처 방법 모두 선택\n① 회사에 공식 신고\n② 인사·노무 담당자 또는 상급자와 상담\n③ 노동조합 또는 근로자 대표와 상담\n④ 노무사·변호사, 고용노동부 등 외부 기관에 상담·신고\n⑤ 부서 이동·전보 요청\n⑥ 휴가·병가·휴직 등 사용\n⑦ 사직·이직\n⑧ 아무런 조치/도움 요청하지 않음\n신청인 정보\n성명\n연락처\n직장 내 괴롭힘 관련 Focus Group Interview(FGI) 개인정보 수집 및 이용 동의서\n본 용역 수행기관인 한국사회조사연구소에서는 「직장 내 괴롭힘 관련 Focus Group Interview(FGI)｣ 관련하여 「개인정보보호법」 제 15조의 규정에 따라 아래와 같이 귀하의 개인정보를 수집 및 이용하고자 합니다.\n○ 개인정보 수집·이용 목적 : FGI 관련 연락, 자료 제공, 직장 내 괴롭힘 관련 추가 문의 등\n○ 수집하는 개인정보 항목 : 소속기업, 성명, 부서, 직위, 연락처, 이메일 등\n○ 개인정보 보유·이용기간 : 조사년도를 포함한 2년(이전에 개인정보 파기를 요청하는 경우 즉시 파기)\n귀하께서는 개인정보 수집·이용 동의에 대해 거부할 권리가 있습니다.\n개인정보 수집 및 이용에 동의하십니까? □동의함 □동의하지 않음 [성명 : ]\n♣ 본 연구에 관심 가져주셔서 진심으로 감사합니다. ♣\nhttps://forms.gle/gi5XLrsLU8cZacoq5\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구의 더 많은 인기글 보러가기\n댓글\n2\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n어쩌면 괜찮은",
