      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n인체바이오 모니터링:임산부,또는 만 6세 이하 자녀를 키우고 계신 분\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.07.27. 16:09\n조회 22\n구독\n인체바이오 모니터링:임산부,또는 만 6세 이하 자녀를 키우고 계신 분\n관련해서 통화시 자세히 안내드립니다\n신청하신분은 재신청 안하셔도 됩니다\n1. 식품의약품안전처의 지원을 받아 전국 8개의 대학교(충북대학교, 중앙대학교, 동아대학교, 동국대학교, 전남대학교, 제주대학교, 경희대학교, 삼육대학교)와 함께 영유아 및 임산부의 건강을 위한 환경유해인자 연구를 진행하고 있습니다.\n이 연구는 인체바이오모니터링을 통해 유해물질 노출을 평가하는 사업으로, [환경유해인자 노출이 스트레스, 우울 및 성장에 미치는 영향]을 위한 연구입니다. 연구에 참여하실 만 6세 이하 영유아와 임산부분을 모집하고 있습니다.\n임신 중이시거나 만 6세 이하 자녀를 키우고 계신 분이라면 참여하실 수 있고요, 연구는 전국 주요 거점에서 특정 날짜와 시간에 맞춰 진행되는 방식으로, 가까운 거점으로 한 번만 방문해 주시면 됩니다. 소요 시간은 약 1시간~ 1시간 30분 정도로, 소정의 사례금도 드립니다.\n2. 답례품 : 농촌사랑 상품권\n1) 임산부 : 리워드 5만원 현장 지급 예정( 현장지급)\n2) 영유아 : 리워드 3만원 현장 지급 예정( 현장지급)\n사전에 온라인으로 사전조사 있습니다.\n현장 오시기전에 채뇨와 소변 가지고 오셔야 합니다 (오시기전에 ㅡ채뇨통과 소변통 택배로 보내드립니다)\n현장에서 설문지 및 채뇨통 제출, 동의서와 수검표 작성.\n- 임산부는 신체계측, 혈압, 채혈 진행, 영유아는 신체계측, 혈압 체크 후 현장에서 리워드 지급. (30분 소요)\n) 채혈 및 소변 채취 진행 (영유아는 소변만 진행), 현장에서 3종의 추가 설문조사 진행\n현장에서 작성하는 3종의 설문지가 양이 꽤 많습니다. 조사를 모두 마치는 데\n1인 기준 최대 1시간 반 정도로 잡으셔야 합니다.\nhttps://forms.gle/WBuAq3LaAcwPNEvA6\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.07.27. 20:56 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n정보 통신 관련 관리자-직업정보 콘텐츠 개발 타당성 조사(재직자대상-여성)_온라인설문 참여자 모집\n좌담회알바좌담회카페\n26.07.27.\n댓글\n1\n인체바이오 모니터링:임산부,또는 만 6세 이하 자녀를 키우고 계신 분\n좌담회알바좌담회카페\n26.07.27.\n댓글\n1\n정보 통신 관련 관리자-직업정보 콘텐츠 개발 타당성 조사(재직자대상-남성)_온라인설문 참여자 모집\n좌담회알바좌담회카페\n26.07.27.\n댓글\n1\n7~8월 중) 30분이내 3-만원) 외국인 관광객 대상 VAN 택시 투어 운영 경험 보유자 줌 혹은 전화 -여성\n좌담회알바좌담회카페\n26.07.27.\n댓글\n2\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
